/* Service worker {{ $version }}. Generated by PwaController; do not edit the output. */
const VERSION = @json($version);
const SHELL = 'shell-' + VERSION;
const PRECACHE = @json($precache);

self.addEventListener('install', (event) => {
    event.waitUntil(caches.open(SHELL).then((cache) => cache.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys()
            .then((keys) => Promise.all(keys.filter((key) => key !== SHELL).map((key) => caches.delete(key))))
            .then(() => self.clients.claim()),
    );
});

self.addEventListener('fetch', (event) => {
    const request = event.request;
    const url = new URL(request.url);

    if (request.method !== 'GET' || url.origin !== self.location.origin) {
        return;
    }

    // Static, fingerprinted assets: cache first.
    if (url.pathname.startsWith('/build/') || url.pathname.startsWith('/icons/') || url.pathname === '/favicon.svg') {
        event.respondWith(
            caches.match(request).then((cached) => cached || fetch(request).then((response) => {
                if (response.ok) {
                    const copy = response.clone();
                    caches.open(SHELL).then((cache) => cache.put(request, copy));
                }
                return response;
            })),
        );
        return;
    }

    // Pages: always the network (never cached, they hold personal data); the offline shell when unreachable.
    if (request.mode === 'navigate') {
        event.respondWith(fetch(request).catch(() => caches.match('/offline')));
    }

    // Everything else (Livewire, API, downloads) goes straight to the network.
});
